ensure_valid_systemd_service_unit() {
    if ! command -v systemd-analyze >/dev/null 2>&1; then
        return 0
    fi

    local verify_log="/tmp/gnss-caster-systemd-verify.log"
    local needs_fallback=0

    if ! systemd-analyze verify "$SERVICE" >"$verify_log" 2>&1; then
        needs_fallback=1
    fi

    if grep -Eqi 'Unknown key name|Failed to parse|Invalid .*|out of range|KSM|MemoryLimit=' "$verify_log" 2>/dev/null; then
        needs_fallback=1
    fi

    if [ "$needs_fallback" -ne 1 ]; then
        return 0
    fi

    echo "WARNING: Generated systemd unit reported unsupported/invalid directives; applying fallback unit profile."
    tail -n 30 "$verify_log" 2>/dev/null | sed 's/^/  /' || true

    write_systemd_service_unit_fallback

    if ! systemd-analyze verify "$SERVICE" >/tmp/gnss-caster-systemd-verify-fallback.log 2>&1; then
        echo "ERROR: Fallback systemd unit verification failed."
        tail -n 40 /tmp/gnss-caster-systemd-verify-fallback.log 2>/dev/null | sed 's/^/  /' || true
        exit 1
    fi
}

run_database_migrations() {
    # Idempotent schema upkeep. Instead of a migration framework, this builds a
    # throwaway Python script that opens the Flask app context and, via
    # SQLAlchemy inspection, creates any missing tables and adds any missing
    # columns - upgrading an existing database in place without data loss. Safe
    # to run repeatedly; install, --repair and first boot all invoke it.
    local migration_script

    if [ ! -x "$VENV/bin/python" ]; then
        echo "ERROR: Python runtime not found for database migration: $VENV/bin/python"
        exit 1
    fi

    migration_script=$(mktemp /tmp/gnss-caster-db-migrate.XXXXXX.py)

cat > "$migration_script" << 'EOF'
import os
import sys

from sqlalchemy import inspect, text

sys.path.insert(0, '/opt/gnss-caster')

from app.web.factory import create_app
from app.db.models import (
    db,
    Admin,
    BaseStation,
    MountPoint,
    Rover,
    RTCMSetting,
    LogEntry,
    Backup,
    SystemSetting,
)

MODELS = [
    Admin,
    BaseStation,
    MountPoint,
    Rover,
    RTCMSetting,
    LogEntry,
    Backup,
    SystemSetting,
]


def quote_identifier(name):
    return '"' + str(name).replace('"', '""') + '"'


def add_missing_columns(engine):
    inspector = inspect(engine)
    dialect = engine.dialect
    changed = []

    with engine.begin() as connection:
        existing_tables = set(inspector.get_table_names())

        for model in MODELS:
            table = model.__table__
            if table.name not in existing_tables:
                continue

            existing_columns = {
                column['name']
                for column in inspector.get_columns(table.name)
            }

            for column in table.columns:
                if column.name in existing_columns or column.primary_key:
                    continue

                column_type = column.type.compile(dialect=dialect)
                statement = (
                    f'ALTER TABLE {quote_identifier(table.name)} '
                    f'ADD COLUMN {quote_identifier(column.name)} {column_type}'
                )
                connection.execute(text(statement))
                changed.append(f'{table.name}.{column.name}')

    return changed


app = create_app()
with app.app_context():
    db.create_all()
    changed_columns = add_missing_columns(db.engine)

    if changed_columns:
        print('Database migration added columns: ' + ', '.join(changed_columns))
    else:
        print('Database schema already current')
EOF

    if ! "$VENV/bin/python" "$migration_script"; then
        rm -f "$migration_script"
        echo "ERROR: Database migration failed"
        exit 1
    fi

    rm -f "$migration_script"
    chown root:"$SERVICE_GROUP" "$INST/db.sqlite" "$INST/db.sqlite-wal" "$INST/db.sqlite-shm" 2>/dev/null || true
    chmod 660 "$INST/db.sqlite" "$INST/db.sqlite-wal" "$INST/db.sqlite-shm" 2>/dev/null || true
}

sync_logrotate_config() {
    local log_retention_days

    echo "Configuring logrotate..."
    log_retention_days=$(get_system_setting_from_db "log_retention" "30")
    case "$log_retention_days" in
        ''|*[!0-9]*)
            log_retention_days=30
            ;;
    esac
    if [ "$log_retention_days" -lt 1 ]; then
        log_retention_days=1
    fi
    if [ "$log_retention_days" -gt 365 ]; then
        log_retention_days=365
    fi

    LOGROTATE_STATUS="daily rotate $log_retention_days day(s)"
    cat > /etc/logrotate.d/gnss-caster << EOF
/var/log/gnss-caster/*.log {
    daily
    # Rotate on size as well as age: a single bad day (a reconnect loop, say)
    # could otherwise fill the SD card before the daily rotation ever runs.
    maxsize 20M
    missingok
    rotate $log_retention_days
    compress
    delaycompress
    notifempty
    create 660 root $SERVICE_GROUP
    sharedscripts
    postrotate
        systemctl reload gnss-caster > /dev/null 2>&1 || true
    endscript
}
EOF
    chmod 644 /etc/logrotate.d/gnss-caster 2>/dev/null || true
}

write_watchdog_script() {
    mkdir -p "$BASE" "$LOG_DIR"

cat > "$BASE/watchdog.sh" << 'EOF'
#!/bin/bash
set +e

export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"

BASE_DIR="/opt/gnss-caster"
CONFIG_FILE="$BASE_DIR/instance/config.yaml"
LOG_FILE="/var/log/gnss-caster/watchdog.log"
STATE_FILE="/run/gnss-caster-watchdog.last"
LOCK_DIR="/run/gnss-caster-watchdog.lock"
MIN_RESTART_INTERVAL=300

get_config_value() {
    local config_key="$1"
    local default_value="$2"
    local config_value=""

    if [ -f "$CONFIG_FILE" ]; then
        config_value=$(awk -F': *' -v lookup_key="$config_key" '
            $0 ~ "^[[:space:]]*" lookup_key ":[[:space:]]*" {
                value = $2
                sub(/[[:space:]]+#.*$/, "", value)
                gsub(/[[:space:]]+$/, "", value)
                print value
                exit
            }
        ' "$CONFIG_FILE" 2>/dev/null)
    fi

    if [ -n "$config_value" ]; then
        printf '%s\n' "$config_value"
    else
        printf '%s\n' "$default_value"
    fi
}

log() {
    mkdir -p "$(dirname "$LOG_FILE")"
    echo "$(date -Is 2>/dev/null || date) $*" >> "$LOG_FILE"
}

if ! mkdir "$LOCK_DIR" 2>/dev/null; then
    exit 0
fi
trap 'rmdir "$LOCK_DIR" 2>/dev/null || true' EXIT

# Do not restart a service deliberately stopped by installation or restore.
if [ -f "$BASE_DIR/sqlite-functions.sh" ]; then
    source "$BASE_DIR/sqlite-functions.sh"
    acquire_maintenance_lock >/dev/null 2>&1 || exit 0
else
    exec 8>/run/gnss-caster-maintenance.lock
    flock -n 8 || exit 0
fi

WEB_PORT=$(get_config_value "web_port" "8080")
HEALTH_URL="http://127.0.0.1:${WEB_PORT}/api/health"
needs_restart=0
reason=""

if ! systemctl is-active --quiet gnss-caster; then
    needs_restart=1
    reason="service inactive"
elif command -v curl >/dev/null 2>&1; then
    if ! curl -sS --max-time 5 -f "$HEALTH_URL" >/dev/null 2>&1; then
        sleep 10
        if ! curl -sS --max-time 5 -f "$HEALTH_URL" >/dev/null 2>&1; then
            needs_restart=1
            reason="health check failed"
        fi
    fi
fi

if [ "$needs_restart" -ne 1 ]; then
    exit 0
fi

now_ts=$(date +%s)
last_ts=0
if [ -f "$STATE_FILE" ]; then
    last_ts=$(cat "$STATE_FILE" 2>/dev/null || echo 0)
fi
case "$last_ts" in
    ''|*[!0-9]*)
        last_ts=0
        ;;
esac

if [ $((now_ts - last_ts)) -lt "$MIN_RESTART_INTERVAL" ]; then
    log "Skipping restart for '$reason'; last restart was $((now_ts - last_ts)) seconds ago"
    exit 0
fi

log "Watchdog detected '$reason'. Capturing local status and restarting gnss-caster only."
{
    echo "===== systemctl status gnss-caster ====="
    systemctl --no-pager --full status gnss-caster 2>/dev/null | tail -n 80 || true
    echo
    echo "===== recent gnss-caster journal ====="
    journalctl -u gnss-caster --since '15 minutes ago' --no-pager 2>/dev/null | tail -n 120 || true
    echo
} >> "$LOG_FILE" 2>&1

echo "$now_ts" > "$STATE_FILE"
systemctl reset-failed gnss-caster >/dev/null 2>&1 || true
systemctl restart gnss-caster >/dev/null 2>&1 || true
sleep 10

if command -v curl >/dev/null 2>&1 && curl -sS --max-time 5 -f "$HEALTH_URL" >/dev/null 2>&1; then
    log "Watchdog restart recovered web health"
else
    log "Watchdog restart completed, but web health is still unavailable"
fi
EOF

    chmod 755 "$BASE/watchdog.sh"
}

sync_cron_jobs() {
    local auto_backup_setting
    local backup_interval_setting
    local backup_cron_expression
    local watchdog_enabled="$ENABLE_WATCHDOG"
    local auto_update_enabled="$ENABLE_AUTO_UPDATE"

    echo "Setting up cron jobs..."
    mkdir -p /etc/cron.d

    if [ "$watchdog_enabled" != "1" ] && [ -f "$MAINTENANCE_CRON" ] && grep -q '/opt/gnss-caster/watchdog.sh' "$MAINTENANCE_CRON" 2>/dev/null; then
        watchdog_enabled=1
    fi
    if [ "$auto_update_enabled" != "1" ] && [ "$SCRIPT_MODE" = "repair" ] && [ -f "$MAINTENANCE_CRON" ] && grep -q '/opt/gnss-caster/update.sh' "$MAINTENANCE_CRON" 2>/dev/null; then
        auto_update_enabled=1
    fi

    cat > "$MAINTENANCE_CRON" << EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
*/5 * * * * root /opt/gnss-caster/monitor.sh >> /var/log/gnss-caster/cron.log 2>&1
EOF

    if [ "$watchdog_enabled" = "1" ]; then
        cat >> "$MAINTENANCE_CRON" << EOF
*/2 * * * * root /opt/gnss-caster/watchdog.sh >> /var/log/gnss-caster/watchdog-cron.log 2>&1
EOF
        WATCHDOG_CRON_STATUS="enabled"
        echo "Health watchdog cron enabled."
    else
        WATCHDOG_CRON_STATUS="disabled"
        echo "Health watchdog cron disabled. Set GNSS_CASTER_ENABLE_WATCHDOG=1 before install to enable it."
    fi

    if [ "$auto_update_enabled" = "1" ]; then
        cat >> "$MAINTENANCE_CRON" << EOF
0 3 * * 0 root /opt/gnss-caster/update.sh >> /var/log/gnss-caster/update.log 2>&1
EOF
        echo "Weekly auto-update cron enabled."
    else
        echo "Weekly auto-update cron disabled. Set GNSS_CASTER_ENABLE_AUTO_UPDATE=1 before install to enable it."
    fi
    chmod 644 "$MAINTENANCE_CRON"

    auto_backup_setting=$(get_system_setting_from_db "auto_backup" "true")
    backup_interval_setting=$(get_system_setting_from_db "backup_interval" "86400")
    backup_cron_expression=$(backup_interval_to_cron_expression "$backup_interval_setting")

    case "$(printf '%s' "$auto_backup_setting" | tr '[:upper:]' '[:lower:]')" in
        1|true|yes|on)
            cat > "$BACKUP_CRON" << EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
$backup_cron_expression root /opt/gnss-caster/backup.sh >> /var/log/gnss-caster/backup-cron.log 2>&1
EOF
            chmod 644 "$BACKUP_CRON"
            BACKUP_CRON_STATUS="enabled ($backup_cron_expression)"
            echo "Automatic backup cron enabled from web settings: $backup_cron_expression"
            ;;
        *)
            rm -f "$BACKUP_CRON"
            BACKUP_CRON_STATUS="disabled in web settings"
            echo "Automatic backup cron disabled by web settings."
            ;;
    esac

    if command -v crontab >/dev/null 2>&1; then
        local tmp_cron_cleanup
        tmp_cron_cleanup=$(mktemp)
        crontab -l 2>/dev/null | \
            grep -v '/opt/gnss-caster/monitor.sh' | \
            grep -v '/opt/gnss-caster/watchdog.sh' | \
            grep -v '/opt/gnss-caster/backup.sh' | \
            grep -v '/opt/gnss-caster/update.sh' > "$tmp_cron_cleanup" || true

        if [ -s "$tmp_cron_cleanup" ]; then
            crontab "$tmp_cron_cleanup" || true
        else
            crontab -r 2>/dev/null || true
        fi
        rm -f "$tmp_cron_cleanup"
    fi
}

run_panic() {
    # Incident response. Immediately revoke every API token and disable 2FA on
    # every admin, so leaked tokens and enrolled TOTP secrets stop working at
    # once. Admins keep their passwords and can re-enrol 2FA / mint new tokens
    # afterwards. Meant for when credentials may be compromised and you cannot
    # rely on the web UI. Runs directly against the database via the app context.
    echo "=== GNSS CASTER PANIC / ACCESS REVOCATION MODE ==="

    if [ ! -x "$VENV/bin/python" ] || [ ! -f "$BASE/main.py" ]; then
        echo "ERROR: GNSS Caster runtime not found under $BASE"
        echo "Run installation first."
        exit 1
    fi

    if [ -t 0 ]; then
        detect_ui_backend
        if ui_enabled; then
            if ! ui_yesno "PANIC - access revocation" "This will revoke ALL API tokens and web sessions, and disable 2FA for ALL admin accounts.\n\nAdmins keep their passwords and can re-enrol afterwards.\n\nContinue?" defaultno; then
                echo "Aborted."
                exit 1
            fi
        else
            echo "This will revoke ALL API tokens and web sessions, and disable 2FA for ALL admins."
            printf "Type REVOKE to continue: "
            read -r panic_confirm
            if [ "$panic_confirm" != "REVOKE" ]; then
                echo "Aborted."
                exit 1
            fi
        fi
    fi

    local panic_script
    panic_script=$(mktemp /tmp/gnss-caster-panic.XXXXXX.py)

cat > "$panic_script" << 'EOF'
import sys

sys.path.insert(0, '/opt/gnss-caster')

from app.web.factory import create_app
from app.db.models import db, ApiToken, Admin

app = create_app()
with app.app_context():
    tokens = ApiToken.query.filter_by(is_active=True).all()
    for token in tokens:
        token.is_active = False

    admins = Admin.query.all()
    for admin in admins:
        admin.session_version = int(admin.session_version or 0) + 1
        admin.totp_enabled = False
        admin.totp_secret = ''
        admin.totp_backup_codes = ''
        admin.totp_pending_secret = ''
        admin.totp_pending_expires = 0

    db.session.commit()
    print(f"Revoked {len(tokens)} active API token(s).")
    print(f"Revoked web sessions and reset 2FA for {len(admins)} admin account(s).")
EOF

    local panic_rc=0
    "$VENV/bin/python" "$panic_script" || panic_rc=$?
    rm -f "$panic_script"

    if [ "$panic_rc" -ne 0 ]; then
        echo "ERROR: access revocation failed"
        exit 1
    fi

    # Cookies are rejected by their DB version on the next request, without
    # changing SECRET_KEY or starting a previously stopped service.
    echo "[OK] API tokens and web sessions revoked; 2FA reset for all admins."
    echo "Re-issue tokens and re-enrol 2FA from the web interface when ready."
}

run_diagnose() {
    echo "=== GNSS CASTER DIAGNOSTIC MODE ==="
    echo "Collecting service, network, and log diagnostics..."

    local ts
    local diag_root
    local diag_name
    local diag_dir
    local archive_path
    local web_port
    local ntrip_port

    ts=$(date +%Y%m%d_%H%M%S)
    diag_root="$BACKUP_DIR/diagnostics"
    diag_name="diagnostic_$ts"
    diag_dir="$diag_root/$diag_name"
    archive_path="$diag_root/${diag_name}.tar.gz"

    mkdir -p "$diag_dir"
    chmod 700 "$diag_root" "$diag_dir" 2>/dev/null || true

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")
    case "$web_port" in
        ''|*[!0-9]*)
            web_port="8080"
            ;;
    esac
    case "$ntrip_port" in
        ''|*[!0-9]*)
            ntrip_port="2101"
            ;;
    esac

    cat > "$diag_dir/README.txt" << EOF
GNSS Caster diagnostic bundle
Generated at: $(date -Is 2>/dev/null || date)
Host: $(hostname 2>/dev/null || echo unknown)

Purpose:
  Capture facts for intermittent SSH/Web drops, service restarts, network loss,
  fail2ban bans, Bluetooth daemon disruption, and application errors.

Notes:
  - instance/config.yaml is redacted before inclusion.
  - Bootstrap admin password files are not copied.
  - Logs may contain IP addresses and usernames.
EOF

    capture_diagnostic_shell "$diag_dir/system.txt" \
        "date -Is; hostnamectl 2>/dev/null || true; uname -a; uptime; free -h; df -h; ps -eo pid,ppid,stat,%cpu,%mem,comm,args --sort=-%mem | head -n 40; command -v vcgencmd >/dev/null 2>&1 && vcgencmd measure_temp || true; command -v vcgencmd >/dev/null 2>&1 && vcgencmd get_throttled || true"

    capture_diagnostic_shell "$diag_dir/services.txt" \
        "for unit in gnss-caster nginx bluetooth fail2ban cron ssh sshd NetworkManager systemd-networkd dhcpcd wpa_supplicant; do echo '===== '\"\$unit\"' ====='; systemctl is-enabled \"\$unit\" 2>/dev/null || true; systemctl is-active \"\$unit\" 2>/dev/null || true; systemctl --no-pager --full status \"\$unit\" 2>/dev/null | tail -n 80 || true; echo; done"

    capture_diagnostic_shell "$diag_dir/journal_gnss_caster.txt" \
        "journalctl -u gnss-caster --since '2 hours ago' --no-pager 2>/dev/null || true"

    capture_diagnostic_shell "$diag_dir/journal_network_stack.txt" \
        "journalctl -u nginx -u bluetooth -u fail2ban -u ssh -u sshd -u NetworkManager -u systemd-networkd -u dhcpcd -u wpa_supplicant --since '2 hours ago' --no-pager 2>/dev/null || true"

    capture_diagnostic_shell "$diag_dir/journal_warnings.txt" \
        "journalctl -p warning --since '2 hours ago' --no-pager 2>/dev/null || true"

    capture_diagnostic_shell "$diag_dir/network.txt" \
        "ip addr; echo; ip route; echo; ss -ltnp 2>/dev/null || ss -ltn 2>/dev/null || true; echo; ss -tanp 2>/dev/null | head -n 120 || true; echo; command -v iw >/dev/null 2>&1 && iw dev || true; command -v iw >/dev/null 2>&1 && iw dev wlan0 link || true; command -v rfkill >/dev/null 2>&1 && rfkill list || true"

    capture_diagnostic_shell "$diag_dir/fail2ban.txt" \
        "command -v fail2ban-client >/dev/null 2>&1 && fail2ban-client status || true; command -v fail2ban-client >/dev/null 2>&1 && fail2ban-client status sshd || true; command -v fail2ban-client >/dev/null 2>&1 && fail2ban-client status gnss-caster-auth || true"

    capture_diagnostic_shell "$diag_dir/health_checks.txt" \
        "echo 'web_port=$web_port'; echo 'ntrip_port=$ntrip_port'; command -v curl >/dev/null 2>&1 && curl -sS --max-time 5 -i http://127.0.0.1:$web_port/api/health || true; echo; ss -ltn 2>/dev/null | grep -E ':($web_port|$ntrip_port)[[:space:]]' || true"

    capture_diagnostic_shell "$diag_dir/gnss_logs_tail.txt" \
        "for f in /var/log/gnss-caster/*.log; do [ -f \"\$f\" ] || continue; echo '===== '\"\$f\"' ====='; tail -n 300 \"\$f\"; echo; done"

    capture_diagnostic_shell "$diag_dir/nginx_logs_tail.txt" \
        "for f in /var/log/nginx/access.log /var/log/nginx/error.log; do [ -f \"\$f\" ] || continue; echo '===== '\"\$f\"' ====='; tail -n 300 \"\$f\"; echo; done"

    capture_diagnostic_shell "$diag_dir/auth_and_reboots.txt" \
        "last -x | head -n 80 2>/dev/null || true; echo; [ -f /var/log/auth.log ] && tail -n 300 /var/log/auth.log || true"

    capture_diagnostic_shell "$diag_dir/cron_and_units.txt" \
        "ls -la /etc/cron.d 2>/dev/null || true; echo; for f in /etc/cron.d/gnss-caster-* /etc/systemd/system/gnss-caster.service /etc/systemd/system/gnss-caster.service.d/* /etc/nginx/sites-available/gnss-caster /etc/nginx/conf.d/gnss-caster-security.conf /etc/fail2ban/jail.d/gnss-caster-auth.local /etc/fail2ban/filter.d/gnss-caster-auth.conf /etc/sudoers.d/gnss-caster /etc/polkit-1/rules.d/49-gnss-caster-bluetooth.rules /opt/gnss-caster/gnss-caster-privileged-helper.sh /opt/gnss-caster/watchdog.sh; do [ -e \"\$f\" ] || continue; echo '===== '\"\$f\"' ====='; sed -n '1,240p' \"\$f\"; echo; done"

    if [ -f "$INST/config.yaml" ]; then
        sed -E \
            -e 's/(secret_key:[[:space:]]*).*/\1<redacted>/I' \
            -e 's/(password[=:][[:space:]]*).*/\1<redacted>/I' \
            -e 's/(token[=:][[:space:]]*).*/\1<redacted>/I' \
            -e 's/(pin[=:][[:space:]]*).*/\1<redacted>/I' \
            "$INST/config.yaml" > "$diag_dir/config.yaml.redacted" 2>/dev/null || true
    fi

    if [ -f "$INST/db.sqlite" ]; then
        capture_diagnostic_shell "$diag_dir/sqlite_integrity.txt" \
            "command -v sqlite3 >/dev/null 2>&1 && sqlite3 '$INST/db.sqlite' 'PRAGMA integrity_check;' || true"
    fi

    tar -czf "$archive_path" -C "$diag_root" "$diag_name"
    chmod 600 "$archive_path" 2>/dev/null || true

    echo ""
    echo "Diagnostic bundle created:"
    echo "  $archive_path"
    echo ""
    echo "Useful next commands:"
    echo "  tar -tzf $archive_path | head"
    echo "  tar -xzf $archive_path -C /tmp"
}

repair_tls_certificate_reader() {
    local factory_file="$APP/web/factory.py"

    if [ ! -f "$factory_file" ]; then
        return 0
    fi

    if grep -q "certificate-info" "$factory_file" 2>/dev/null; then
        echo "TLS certificate reader already supports privileged helper."
        return 0
    fi

    echo "Patching installed TLS certificate reader for Let's Encrypt permissions..."

    "$VENV/bin/python" - "$factory_file" << 'PYTHON_TLS_REPAIR'
import re
import sys
from pathlib import Path

factory_path = Path(sys.argv[1])
source = factory_path.read_text(encoding='utf-8')

helper_function = r'''
        def _decode_certificate_with_privileged_helper(cert_path):
            certificate_path = str(cert_path or '').strip()
            helper_result = _run_privileged_helper(
                ['certificate-info', certificate_path],
                timeout=30,
            )
            helper_output = str(helper_result.stdout or '').strip()
            if not helper_output:
                raise RuntimeError('privileged helper returned no certificate data')
            return json.loads(helper_output)
'''

load_certificate_function = r'''
        def _load_certificate_info(cert_path):
            certificate_path = str(cert_path or '').strip()
            if not certificate_path:
                return {}

            temp_cert_path = ''
            try:
                try:
                    if not os.path.isfile(certificate_path):
                        raise FileNotFoundError(
                            'certificate file is not readable by the service user'
                        )

                    with open(certificate_path, 'r', encoding='utf-8', errors='ignore') as cert_file:
                        pem_text = cert_file.read()

                    begin_marker = '-----BEGIN CERTIFICATE-----'
                    end_marker = '-----END CERTIFICATE-----'
                    if pem_text.count(begin_marker) > 1 and end_marker in pem_text:
                        first_certificate = pem_text.split(end_marker, 1)[0] + end_marker + '\n'
                        with tempfile.NamedTemporaryFile(
                            mode='w',
                            encoding='utf-8',
                            delete=False
                        ) as temp_cert_file:
                            temp_cert_file.write(first_certificate)
                            temp_cert_path = temp_cert_file.name
                        decode_path = temp_cert_path
                    else:
                        decode_path = certificate_path

                    decoded = ssl._ssl._test_decode_cert(decode_path)
                except Exception as direct_decode_error:
                    try:
                        decoded = _decode_certificate_with_privileged_helper(certificate_path)
                    except Exception as helper_decode_error:
                        raise RuntimeError(
                            f'direct certificate decode failed: {direct_decode_error}; '
                            f'privileged helper decode failed: {helper_decode_error}'
                        ) from helper_decode_error

                subject = decoded.get('subject', ())
                issuer = decoded.get('issuer', ())
                san_entries = decoded.get('subjectAltName', ()) or ()
                serial_number = str(decoded.get('serialNumber', '') or '').strip()

                not_before_dt = _parse_cert_datetime(decoded.get('notBefore'))
                not_after_dt = _parse_cert_datetime(decoded.get('notAfter'))
                now_dt = datetime.now(timezone.utc)

                days_remaining = None
                if not_after_dt is not None:
                    remaining_seconds = (not_after_dt - now_dt).total_seconds()
                    days_remaining = int(remaining_seconds // 86400)

                common_name = _extract_dn_value(subject, 'commonName')
                organization_name = _extract_dn_value(subject, 'organizationName')

                san_values = []
                for san_type, san_value in san_entries:
                    san_values.append(f'{san_type}:{san_value}')

                return {
                    'subject': _normalize_dn_name(subject),
                    'subject_common_name': common_name,
                    'subject_organization': organization_name,
                    'issuer': _normalize_dn_name(issuer),
                    'issuer_common_name': _extract_dn_value(issuer, 'commonName'),
                    'serial_number': serial_number,
                    'subject_alt_names': san_values,
                    'not_before': not_before_dt.isoformat() if not_before_dt else '',
                    'not_after': not_after_dt.isoformat() if not_after_dt else '',
                    'days_remaining': days_remaining,
                    'expired': bool(not_after_dt and now_dt > not_after_dt),
                    'valid_now': bool(
                        not_before_dt and not_after_dt and not_before_dt <= now_dt <= not_after_dt
                    ),
                }
            except Exception as cert_error:
                logger.warning(f'Unable to decode TLS certificate "{certificate_path}": {cert_error}')
                return {'error': str(cert_error)}
            finally:
                if temp_cert_path:
                    try:
                        os.unlink(temp_cert_path)
                    except Exception:
                        pass
'''

replacement = helper_function + load_certificate_function + '\n        def _read_current_tls_configuration():'
source, function_replacements = re.subn(
    r'\n        def _load_certificate_info\(cert_path\):\n.*?\n        def _read_current_tls_configuration\(\):',
    lambda match: '\n' + replacement,
    source,
    count=1,
    flags=re.S,
)

if function_replacements != 1:
    raise SystemExit('Unable to patch _load_certificate_info in installed factory.py')

old_presence_block = """            if certificate_path and os.path.isfile(certificate_path):
                tls_info['certificate_present'] = True
                tls_info['certificate_info'] = _load_certificate_info(certificate_path)
"""
new_presence_block = """            if certificate_path:
                certificate_info = _load_certificate_info(certificate_path)
                tls_info['certificate_info'] = certificate_info
                tls_info['certificate_present'] = bool(
                    certificate_info and not certificate_info.get('error')
                )
"""

if old_presence_block in source:
    source = source.replace(old_presence_block, new_presence_block, 1)
elif new_presence_block not in source:
    raise SystemExit('Unable to patch TLS certificate presence check in installed factory.py')

factory_path.write_text(source, encoding='utf-8')
PYTHON_TLS_REPAIR
}

repair_ui_interaction_fixes() {
    local base_template="$APP/web/templates/base.html"
    local dashboard_template="$APP/web/templates/dashboard.html"
    local system_template="$APP/web/templates/system_configuration.html"

    if [ ! -f "$dashboard_template" ] && [ ! -f "$system_template" ]; then
        return 0
    fi

    echo "Patching installed UI interactions for custom power modal and toast notifications..."

    if ! "$VENV/bin/python" - "$base_template" "$dashboard_template" "$system_template" << 'PYTHON_UI_REPAIR'
import re
import sys
from pathlib import Path

base_path = Path(sys.argv[1])
dashboard_path = Path(sys.argv[2])
system_path = Path(sys.argv[3])


def read_text(path):
    if not path.exists():
        return ''
    return path.read_text(encoding='utf-8')


def write_if_changed(path, old_text, new_text):
    if new_text != old_text:
        path.write_text(new_text, encoding='utf-8')
        print(f'patched {path}')


if base_path.exists():
    base_source = read_text(base_path)
    patched_base = base_source
    if '.toast.warning' not in patched_base:
        patched_base = patched_base.replace(
            """        .toast.success {
            border-left-color: #48bb78;
        }

        .toast.error {""",
            """        .toast.success {
            border-left-color: #48bb78;
        }

        .toast.warning {
            border-left-color: #ed8936;
        }

        .toast.error {""",
            1,
        )
    if '.toast.info' not in patched_base:
        patched_base = patched_base.replace(
            """        .toast.warning {
            border-left-color: #ed8936;
        }

        .toast.error {""",
            """        .toast.warning {
            border-left-color: #ed8936;
        }

        .toast.info {
            border-left-color: #4299e1;
        }

        .toast.error {""",
            1,
        )
    if 'window.appNotifyWarning' not in patched_base:
        patched_base = patched_base.replace(
            """        window.appNotifySuccess = function(message) {
            showInlineNotification('success', message);
        };

        window.appNotifyError = function(message) {""",
            """        window.appNotifySuccess = function(message) {
            showInlineNotification('success', message);
        };

        window.appNotifyWarning = function(message) {
            showInlineNotification('warning', message, 6000);
        };

        window.appNotifyError = function(message) {""",
            1,
        )
    if 'window.appNotifyInfo' not in patched_base:
        patched_base = patched_base.replace(
            """        window.appNotifyWarning = function(message) {
            showInlineNotification('warning', message, 6000);
        };

        window.appNotifyError = function(message) {""",
            """        window.appNotifyWarning = function(message) {
            showInlineNotification('warning', message, 6000);
        };

        window.appNotifyInfo = function(message) {
            showInlineNotification('info', message);
        };

        window.appNotifyError = function(message) {""",
            1,
        )
    if 'window.appNotifyFromMessage' not in patched_base:
        patched_base = patched_base.replace(
            """        window.appNotifyError = function(message) {
            showInlineNotification('error', message);
        };
""",
            """        window.appNotifyError = function(message) {
            showInlineNotification('error', message);
        };

        window.appNotifyFromMessage = function(message) {
            const text = String(message || '').trim();
            if (!text) return;

            if (/^error[:\\s]/i.test(text)) {
                window.appNotifyError(text.replace(/^error[:\\s]*/i, ''));
            } else if (/^success[:\\s]/i.test(text)) {
                window.appNotifySuccess(text.replace(/^success[:\\s]*/i, ''));
            } else if (/^warning[:\\s]/i.test(text)) {
                window.appNotifyWarning(text.replace(/^warning[:\\s]*/i, ''));
            } else {
                window.appNotifyInfo(text);
            }
        };

        window.alert = function(message) {
            window.appNotifyFromMessage(message);
        };
""",
            1,
        )
    write_if_changed(base_path, base_source, patched_base)


if dashboard_path.exists():
    dashboard_source = read_text(dashboard_path)
    patched_dashboard = dashboard_source
    patched_dashboard = patched_dashboard.replace(
        'Use this only for recovery. Other administrators will be forced to change the password after login. You may also reset the current session account here if needed.',
        'Set a new password for the selected administrator. If this is another account, that user will be asked to change it at the next login.',
    )
    patched_dashboard = patched_dashboard.replace('Confirm Temporary Password', 'Confirm New Password')
    patched_dashboard = patched_dashboard.replace('Temporary Password', 'New Password')
    patched_dashboard = patched_dashboard.replace(
        'Temporary password must be at least 12 characters long',
        'New password must be at least 12 characters long',
    )

    write_if_changed(dashboard_path, dashboard_source, patched_dashboard)


if system_path.exists():
    system_source = read_text(system_path)
    patched_system = system_source
    patched_system = patched_system.replace(
        "        setInlineNote('saveResultNote', saveResultNote);\n",
        """        const saveResultContainer = document.getElementById('saveResultNote');
        if (saveResultContainer) {
            saveResultContainer.innerHTML = '';
        }
""",
        1,
    )

    old_general_note_function = """    function setGeneralInlineNote(type, text) {
        saveResultNote = {
            type: String(type || 'info').trim().toLowerCase(),
            text: String(text || '').trim()
        };
        renderGeneralFieldHints();
    }
"""
    new_general_note_function = """    function setGeneralInlineNote(type, text) {
        const normalizedType = String(type || 'info').trim().toLowerCase();
        const message = String(text || '').trim();
        if (!message) {
            return;
        }

        if (normalizedType === 'error' && window.appNotifyError) {
            window.appNotifyError(message);
        } else if (normalizedType === 'warning' && window.appNotifyWarning) {
            window.appNotifyWarning(message);
        } else if (window.appNotifySuccess) {
            window.appNotifySuccess(message);
        }
    }
"""
    if old_general_note_function in patched_system:
        patched_system = patched_system.replace(old_general_note_function, new_general_note_function, 1)

    old_hostname_note = """        saveResultNote = {
            type: 'info',
            text: 'System Name copied from the OS hostname. Save the page to persist it.'
        };
        renderGeneralFieldHints();
"""
    new_hostname_note = """        setGeneralInlineNote('success', 'System Name copied from the OS hostname. Save the page to persist it.');
        renderGeneralFieldHints();
"""
    if old_hostname_note in patched_system:
        patched_system = patched_system.replace(old_hostname_note, new_hostname_note, 1)

    old_success = """        .then(data => {
            const warnings = Array.isArray(data.warnings) ? data.warnings.filter(Boolean) : [];
            saveResultNote = {
                type: warnings.length ? 'warning' : 'success',
                text: warnings.length
                    ? `${data.message || 'System settings saved'} Warnings: ${warnings.join(' ')}`
                    : (data.message || 'System settings saved successfully')
            };
            renderGeneralFieldHints();
            Promise.all([loadSystemSettings(), loadMaintenanceInfo(), loadTlsInfo()])
                .then(() => {
                    renderSecurityOverview();
                });
        })
        .catch(error => {
            console.error('Error saving system settings:', error);
            saveResultNote = {
                type: 'error',
                text: error.message || 'Failed to save system settings'
            };
            renderGeneralFieldHints();
        });"""
    new_success = """        .then(data => {
            const warnings = Array.isArray(data.warnings) ? data.warnings.filter(Boolean) : [];
            const saveMessage = warnings.length
                ? `${data.message || 'System settings saved'} Warnings: ${warnings.join(' ')}`
                : (data.message || 'System settings saved successfully');
            saveResultNote = {
                type: warnings.length ? 'warning' : 'success',
                text: saveMessage
            };
            renderGeneralFieldHints();
            if (warnings.length && window.appNotifyWarning) {
                window.appNotifyWarning(saveMessage);
            } else if (window.appNotifySuccess) {
                window.appNotifySuccess(saveMessage);
            }
            Promise.all([loadSystemSettings(), loadMaintenanceInfo(), loadTlsInfo()])
                .then(() => {
                    renderSecurityOverview();
                });
        })
        .catch(error => {
            console.error('Error saving system settings:', error);
            saveResultNote = {
                type: 'error',
                text: error.message || 'Failed to save system settings'
            };
            renderGeneralFieldHints();
            if (window.appNotifyError) {
                window.appNotifyError(saveResultNote.text);
            }
        });"""
    if old_success in patched_system:
        patched_system = patched_system.replace(old_success, new_success, 1)
    write_if_changed(system_path, system_source, patched_system)
PYTHON_UI_REPAIR
    then
        echo "WARNING: UI interaction patch could not be fully applied. A full reinstall will still include the UI fixes."
    fi
}

