"""
RTCM Streaming Manager
Handles distribution of RTCM data to connected clients
"""
import time
import logging
import json
from collections import defaultdict
from threading import Lock, Thread, Event
from queue import Queue, Empty, Full
import socket
from flask import has_app_context
from app.db.models import RTCMSetting, db, MountPoint
from app.rtcm.registry import (
    get_message_description,
    get_message_group,
    is_default_rtcm_enabled,
)

logger = logging.getLogger(__name__)

class RTCMStreamManager:
    """Manages RTCM data streaming to connected clients"""
    
    def __init__(self):
        self.streams = defaultdict(set)  # (base_id, mountpoint_id) -> set of client sockets
        self.client_routes = {}
        self.client_senders = {}
        self.client_queue_frames = 64
        self.client_max_frame_age = 2.0
        self._pending_sent_bytes = defaultdict(int)
        self.buffers = defaultdict(bytearray)
        self.lock = Lock()
        self.stats = defaultdict(lambda: {
            'clients': 0,
            'bytes_sent': 0,
            'last_activity': 0,
            'messages_sent': 0,
            'message_types': defaultdict(int),
            'crc_failures': 0,
            # Frames successfully decoded from the receiver, regardless of
            # whether any rover was connected to receive them. Without this,
            # a working base station with no rovers looks identical to a
            # broken parser.
            'frames_parsed': 0,
            'last_frame_at': 0.0,
            'message_types_seen': defaultdict(int),
        })
        # ── RTCM filter cache ────────────────────────────────────────────────
        # Populated lazily from DB on first use; invalidated whenever the admin
        # changes RTCM settings through the UI.  Avoids an SQL SELECT on every
        # single RTCM frame in the broadcast hot-path (can be 10 + types/sec).
        #
        # Structure:
        #   _global_filter: {msg_type(int): bool}         – from RTCMSetting
        #   _mp_filter:     {mountpoint_id(int): {msg_type(int): bool}} – per-mountpoint overrides
        #   _filter_loaded: bool – False → needs a DB refresh
        self._filter_lock = Lock()          # separate from self.lock so broadcast stays fast
        self._global_filter: dict = {}
        self._mp_filter: dict = {}
        self._filter_loaded: bool = False

    # ── Filter cache management ──────────────────────────────────────────────

    def _load_filter_cache(self):
        """Read RTCM enable/disable settings from DB into memory.

        Called lazily once and then only after an explicit invalidation.
        Must be called while NOT holding self._filter_lock (it acquires it
        internally at the end to do the atomic swap).
        """
        global_map: dict = {}
        mp_map: dict = {}

        try:
            # Global filter
            for setting in RTCMSetting.query.all():
                global_map[int(setting.msg_type)] = bool(setting.enabled)

            # Per-mountpoint overrides
            for mp in MountPoint.query.all():
                if not mp.rtcm_settings:
                    continue
                try:
                    overrides = json.loads(mp.rtcm_settings)
                    mp_map[int(mp.id)] = {
                        int(k): bool(v) for k, v in overrides.items()
                        if str(k).isdigit()
                    }
                except Exception:
                    pass
        except Exception as e:
            logger.error(f"RTCMStreamManager: failed to load filter cache: {e}")
            # Leave existing cache intact rather than wiping it on DB error.
            return

        with self._filter_lock:
            self._global_filter = global_map
            self._mp_filter = mp_map
            self._filter_loaded = True
        logger.debug(
            f"RTCMStreamManager: filter cache loaded – "
            f"{len(global_map)} global types, {len(mp_map)} mountpoint overrides"
        )

    def invalidate_filter_cache(self):
        """Mark the filter cache as stale so it is reloaded before the next frame.

        Call this from the API routes that save RTCMSetting or MountPoint changes
        (inside an app_context, after db.session.commit()).
        """
        with self._filter_lock:
            self._filter_loaded = False
        logger.debug("RTCMStreamManager: filter cache invalidated")

    @staticmethod
    def _normalize_stream_key(base_id, mountpoint_id):
        return (int(base_id), int(mountpoint_id))

    def _get_base_client_count_locked(self, base_id):
        normalized_base_id = int(base_id)
        total_clients = 0
        for (stream_base_id, _), clients in self.streams.items():
            if stream_base_id == normalized_base_id:
                total_clients += len(clients)
        return total_clients

    def parse_message_type(self, data):
        """Extract the RTCM3 message type from a frame, or None.

        The message number lives in the first 12 bits of the payload, i.e.
        bytes 3 and 4 of the frame (after the 3-byte header).
        """
        if not data or len(data) < 6:
            return None
        if data[0] != 0xD3:
            return None
        try:
            return (data[3] << 4) | (data[4] >> 4)
        except (IndexError, TypeError):
            return None

    def warm_filter_cache(self):
        """Load the RTCM filter cache up front, inside an app context.

        Called when a station connects so the broadcast path afterwards never
        has to touch the database - it runs several times a second and a Flask
        context per call is wasted work on a small board.
        """
        try:
            with self._filter_lock:
                needs_load = not self._filter_loaded
            if needs_load:
                self._load_filter_cache()
        except Exception as warm_error:
            logger.warning(f'RTCM filter cache warm-up failed: {warm_error}')

    def is_message_allowed(self, msg_type, mountpoint_id=None):
        """Return True if this RTCM message type should be forwarded.

        Uses an in-memory cache so NO SQL is executed on the hot broadcast path.
        The cache is loaded lazily on first call and re-loaded after any call to
        invalidate_filter_cache().
        """
        if msg_type is None:
            return True

        # Ensure cache is warm (load without holding _filter_lock to avoid
        # blocking broadcast while doing DB I/O).
        with self._filter_lock:
            loaded = self._filter_loaded
        if not loaded:
            self._load_filter_cache()

        with self._filter_lock:
            global_filter = self._global_filter
            mp_filter = self._mp_filter

        # Global rule
        if msg_type in global_filter:
            globally_enabled = global_filter[msg_type]
        else:
            # Unknown type – create default setting in DB (once) and cache it.
            globally_enabled = is_default_rtcm_enabled(msg_type)
            try:
                # The broadcast path deliberately runs without an application
                # context. Persisting a newly seen message type is a nicety,
                # not a requirement - the in-memory cache below is what the
                # stream actually needs, so skip the write when there is no
                # context rather than raising on the hot path.
                if not has_app_context():
                    raise RuntimeError('no application context on the broadcast path')
                existing = RTCMSetting.query.filter_by(msg_type=msg_type).first()
                if not existing:
                    new_setting = RTCMSetting(
                        msg_type=msg_type,
                        enabled=globally_enabled,
                        description=get_message_description(msg_type),
                        group=get_message_group(msg_type),
                    )
                    db.session.add(new_setting)
                    db.session.commit()
            except Exception as e:
                logger.debug(f"RTCMStreamManager: setting for type {msg_type} not stored: {e}")
            # Update cache immediately so we don't hit DB again for same type.
            with self._filter_lock:
                self._global_filter[msg_type] = globally_enabled

        if not globally_enabled:
            return False

        # Per-mountpoint override
        if mountpoint_id is not None:
            mid = int(mountpoint_id)
            mp_overrides = mp_filter.get(mid, {})
            if msg_type in mp_overrides and not mp_overrides[msg_type]:
                return False

        return True
    
    def register_client(self, base_id, mountpoint_id, client_socket):
        """Register client for a base station mountpoint"""
        stream_key = self._normalize_stream_key(base_id, mountpoint_id)
        with self.lock:
            if client_socket in self.client_routes:
                raise ValueError('Client socket is already registered')
            sender = {
                'queue': Queue(maxsize=self.client_queue_frames),
                'stop': Event(),
            }
            thread = Thread(
                target=self._send_client_frames,
                args=(stream_key, client_socket, sender),
                daemon=True, name=f'RTCM-Sender-{client_socket.fileno()}',
            )
            sender['thread'] = thread
            self.client_senders[client_socket] = sender
            self.streams[stream_key].add(client_socket)
            self.client_routes[client_socket] = stream_key
            self.stats[stream_key[0]]['clients'] = self._get_base_client_count_locked(stream_key[0])
            self.stats[stream_key[0]]['last_activity'] = time.monotonic()
            logger.info(
                f"Client registered for base {stream_key[0]}, mountpoint {stream_key[1]}. "
                f"Total clients: {self.stats[stream_key[0]]['clients']}"
            )
        try:
            thread.start()
        except Exception:
            self.unregister_client(*stream_key, client_socket)
            raise

    def _send_client_frames(self, stream_key, client_socket, sender):
        """One writer per socket; receiver/broadcast threads never wait for TCP."""
        try:
            while not sender['stop'].is_set():
                try:
                    queued_at, data, msg_type = sender['queue'].get(timeout=0.25)
                except Empty:
                    continue
                if sender['stop'].is_set():
                    break
                if time.monotonic() - queued_at > self.client_max_frame_age:
                    logger.warning('Disconnecting rover: RTCM send queue is stale')
                    break
                # The NTRIP handler sets a fixed streaming socket timeout before
                # registration. Do not change it here: the reader shares it.
                client_socket.sendall(data)
                with self.lock:
                    stats = self.stats[stream_key[0]]
                    stats['bytes_sent'] += len(data)
                    stats['messages_sent'] += 1
                    if msg_type:
                        stats['message_types'][msg_type] += 1
                    self._pending_sent_bytes[stream_key[0]] += len(data)
        except Exception as exc:
            logger.debug('RTCM sender disconnected: %s', exc)
        finally:
            self.unregister_client(*stream_key, client_socket)

    def take_sent_bytes(self, base_id):
        """Drain completed sends for the receiver's periodic database flush."""
        with self.lock:
            return self._pending_sent_bytes.pop(int(base_id), 0)
    
    def unregister_client(self, base_id, mountpoint_id, client_socket):
        """Unregister client from a base station mountpoint"""
        stream_key = self._normalize_stream_key(base_id, mountpoint_id)
        sender = None
        with self.lock:
            clients = self.streams.get(stream_key)
            if clients and client_socket in clients:
                clients.remove(client_socket)
                if not clients:
                    self.streams.pop(stream_key, None)
                if self.client_routes.get(client_socket) == stream_key:
                    self.client_routes.pop(client_socket, None)
                    sender = self.client_senders.pop(client_socket, None)
                    if sender:
                        sender['stop'].set()

                self.stats[stream_key[0]]['clients'] = self._get_base_client_count_locked(stream_key[0])
                self.stats[stream_key[0]]['last_activity'] = time.monotonic()
                logger.info(
                    f"Client unregistered from base {stream_key[0]}, mountpoint {stream_key[1]}. "
                    f"Remaining clients: {self.stats[stream_key[0]]['clients']}"
                )
        if sender:
            # Wake both a blocked reader and writer, including after queue overflow.
            try:
                client_socket.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            try:
                client_socket.close()
            except OSError:
                pass

    def unregister_client_socket(self, client_socket):
        """Unregister client by socket reference only"""
        with self.lock:
            stream_key = self.client_routes.get(client_socket)

        if not stream_key:
            return

        self.unregister_client(stream_key[0], stream_key[1], client_socket)
    
    def broadcast(self, base_id, data, mountpoint_id=None):
        """Queue a frame without blocking; return the number of accepted queues."""
        if not data:
            return 0
        if len(data) > 1029:
            raise ValueError('RTCM frame exceeds the protocol size limit')
        data = bytes(data)

        msg_type = self.parse_message_type(data)

        dead_clients = []
        delivered_clients = 0
        normalized_base_id = int(base_id)

        with self.lock:
            # Mark the base as alive as soon as a frame arrives, before the
            # early return below. Otherwise a perfectly healthy station with no
            # rover attached never refreshed its activity timestamp, and
            # cleanup_inactive() wiped its stats and receive buffer after five
            # minutes ("Cleaned up inactive base station N" in the log).
            # Monotonic on purpose - see cleanup_inactive().
            self.stats[normalized_base_id]['last_activity'] = time.monotonic()

            if mountpoint_id is not None:
                stream_keys = [self._normalize_stream_key(normalized_base_id, mountpoint_id)]
            else:
                stream_keys = [
                    stream_key for stream_key in self.streams.keys()
                    if stream_key[0] == normalized_base_id
                ]

        if not stream_keys:
            return 0

        for stream_key in stream_keys:
            stream_mountpoint_id = stream_key[1]
            if not self.is_message_allowed(msg_type, stream_mountpoint_id):
                logger.debug(
                    f"Message type {msg_type} not allowed for mountpoint {stream_mountpoint_id}, skipping"
                )
                continue

            with self.lock:
                clients_to_notify = list(self.streams.get(stream_key, set()))

            for client in clients_to_notify:
                try:
                    with self.lock:
                        sender = self.client_senders.get(client)
                        if not sender or sender['stop'].is_set():
                            continue
                        sender['queue'].put_nowait((time.monotonic(), data, msg_type))
                        delivered_clients += 1
                except Full:
                    logger.warning('Disconnecting rover: RTCM send queue is full')
                    dead_clients.append((stream_key, client))

        # Clean up dead clients
        for stream_key, dead_client in dead_clients:
            self.unregister_client(stream_key[0], stream_key[1], dead_client)
        
        return delivered_clients

    @staticmethod
    def compute_crc24q(payload):
        """CRC-24Q checksum used by RTCM3 (Qualcomm polynomial 0x1864CFB)."""
        crc = 0
        for byte in payload:
            crc ^= byte << 16
            for _ in range(8):
                crc <<= 1
                if crc & 0x1000000:
                    crc ^= 0x1864CFB
        return crc & 0xFFFFFF

    def is_valid_rtcm_frame(self, frame):
        """Validate a complete RTCM3 frame: preamble, length and CRC-24Q.

        A frame is 3 header bytes (0xD3, 6 reserved bits + 10 length bits),
        the payload, then a 3-byte CRC computed over the header and payload.
        """
        if not frame or len(frame) < 6:
            return False
        if frame[0] != 0xD3:
            return False

        payload_length = ((frame[1] & 0x03) << 8) | frame[2]
        if len(frame) != 3 + payload_length + 3:
            return False

        expected_crc = (frame[-3] << 16) | (frame[-2] << 8) | frame[-1]
        return self.compute_crc24q(frame[:-3]) == expected_crc

    def reset_stream_buffer(self, base_id):
        """Drop any half-received frame for a base station.

        Called when a receiver reconnects: the bytes left over from the
        interrupted frame would otherwise be glued to the start of the new
        stream, producing a corrupt frame and a spurious CRC failure.
        """
        try:
            normalized_base_id = int(base_id)
        except (TypeError, ValueError):
            return
        with self.lock:
            buffer = self.buffers.get(normalized_base_id)
            if buffer:
                buffer.clear()

    def broadcast_stream(self, base_id, data, mountpoint_id=None):
        """Parse and queue RTCM frames; return queued frame deliveries and bytes.

        Completed sends are counted by the sender threads, not by these returns.
        """
        if not data:
            return 0, 0

        normalized_base_id = int(base_id)
        frames = []

        with self.lock:
            buffer = self.buffers[normalized_base_id]
            buffer.extend(data)

            while True:
                while buffer and buffer[0] != 0xD3:
                    del buffer[0]

                if len(buffer) < 3:
                    break

                payload_length = ((buffer[1] & 0x03) << 8) | buffer[2]
                frame_length = 3 + payload_length + 3

                if frame_length <= 6:
                    del buffer[0]
                    continue

                if len(buffer) < frame_length:
                    break

                candidate_frame = bytes(buffer[:frame_length])
                if not self.is_valid_rtcm_frame(candidate_frame):
                    self.stats[normalized_base_id]['crc_failures'] += 1
                    logger.debug(
                        f"Discarded RTCM frame with invalid CRC for base {normalized_base_id}"
                    )
                    del buffer[0]
                    continue

                frames.append(candidate_frame)
                self.stats[normalized_base_id]['frames_parsed'] += 1
                self.stats[normalized_base_id]['last_frame_at'] = time.monotonic()
                parsed_type = self.parse_message_type(candidate_frame)
                if parsed_type:
                    self.stats[normalized_base_id]['message_types_seen'][parsed_type] += 1
                del buffer[:frame_length]

            if len(buffer) > 8192:
                del buffer[:-4096]

        delivered_clients = 0
        delivered_bytes = 0

        for frame in frames:
            frame_deliveries = self.broadcast(normalized_base_id, frame, mountpoint_id=mountpoint_id)
            delivered_clients += frame_deliveries
            delivered_bytes += len(frame) * frame_deliveries

        return delivered_clients, delivered_bytes
    
    def get_stats(self, base_id=None):
        """Get streaming statistics"""
        with self.lock:
            if base_id:
                stats = dict(self.stats.get(base_id, {}))
                # Convert defaultdicts to plain dicts for JSON serialisation
                if 'message_types' in stats:
                    stats['message_types'] = dict(stats['message_types'])
                if 'message_types_seen' in stats:
                    stats['message_types_seen'] = dict(stats['message_types_seen'])
                return stats
            return {k: dict(v) for k, v in self.stats.items()}
    
    def get_client_count(self, base_id):
        """Get number of clients for a base station"""
        with self.lock:
            return self._get_base_client_count_locked(base_id)
    
    def cleanup_inactive(self, timeout=300):
        """Clean up streams with no activity for timeout seconds.

        Monotonic to match last_activity: the host clock can be stepped (a Pi
        has no RTC, and the GNSS time sync moves it on purpose), and a wall
        clock comparison would wipe a healthy station the instant that happens.
        """
        current_time = time.monotonic()
        inactive_bases = []
        
        with self.lock:
            for base_id, stat in self.stats.items():
                if current_time - stat['last_activity'] > timeout and stat['clients'] == 0:
                    inactive_bases.append(base_id)
            
            for base_id in inactive_bases:
                stream_keys = [
                    stream_key for stream_key in self.streams.keys()
                    if stream_key[0] == base_id
                ]
                for stream_key in stream_keys:
                    for client_socket in list(self.streams.get(stream_key, set())):
                        if self.client_routes.get(client_socket) == stream_key:
                            self.client_routes.pop(client_socket, None)
                    self.streams.pop(stream_key, None)
                self.buffers.pop(base_id, None)
                if base_id in self.stats:
                    del self.stats[base_id]
                logger.info(f"Cleaned up inactive base station {base_id}")
    
    def get_message_type_stats(self):
        """Get statistics by message type across all streams"""
        type_stats = defaultdict(lambda: {'count': 0, 'bytes': 0, 'streams': set()})
        
        with self.lock:
            for base_id, stats in self.stats.items():
                for msg_type, count in stats.get('message_types', {}).items():
                    type_stats[msg_type]['count'] += count
                    type_stats[msg_type]['streams'].add(base_id)
        
        # Convert sets to counts
        for msg_type in type_stats:
            type_stats[msg_type]['stream_count'] = len(type_stats[msg_type]['streams'])
            del type_stats[msg_type]['streams']
        
        return dict(type_stats)

# Global instance
stream_manager = RTCMStreamManager()
EOF

