cat > $APP/ntrip/core.py << 'EOF'
"""
NTRIP Server Implementation
Handles NTRIP client connections and authentication
"""
import socket
import os
import stat
from contextlib import contextmanager
import threading
import base64
import uuid
import time
import logging
import bcrypt
from app.db.models import Rover, MountPoint, db, LogEntry, SystemSetting
from sqlalchemy import text
from app.rtcm.stream import stream_manager
from app import notify

try:
    # Version is generated by the installer from CASTER_VERSION.
    from app.version import __version__ as CASTER_VERSION
except Exception:  # pragma: no cover - fallback if version module is missing
    CASTER_VERSION = "unknown"

logger = logging.getLogger(__name__)

ADMISSION_LOCK = '/var/lib/gnss-caster-admission.lock'


@contextmanager
def admission_guard():
    """Reserve admission until its database commit; maintenance owns EX."""
    import fcntl
    descriptor = os.open(ADMISSION_LOCK, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        info = os.fstat(descriptor)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1 or info.st_mode & 0o022:
            raise OSError('Unsafe admission lock')
        fcntl.flock(descriptor, fcntl.LOCK_SH | fcntl.LOCK_NB)
        yield
    finally:
        os.close(descriptor)


class NTRIPServer:
    def __init__(self, host='0.0.0.0', port=2101):
        self.host = host
        self.port = port
        self.running = False
        self.server_socket = None
        self.connections = {}
        self.connection_lock = threading.Lock()
        self.auth_lock = threading.RLock()
        self.header_max_bytes = 16384
        self.header_timeout = 10.0
        self._stop_event = threading.Event()
        self.max_connections = 100
        self.auth_ip_window_seconds = 600
        self.auth_ip_block_seconds = 600
        self.auth_ip_max_failures = 10
        self.auth_ip_failures = {}
        self.stats = {
            'total_connections': 0,
            'current_connections': 0,
            'failed_auth': 0,
            'bytes_sent': 0,
            'rovers_connected': 0
        }
        self.app = None  # Will be set by init_app

    def _prune_auth_ip_failures(self, now_ts=None):
        with self.auth_lock:
            current_ts = int(now_ts or time.time())
            stale_ips = []

            for ip_address, entry in self.auth_ip_failures.items():
                recent_failures = [
                    ts for ts in entry.get('failures', [])
                    if (current_ts - int(ts)) <= self.auth_ip_window_seconds
                ]
                blocked_until = int(entry.get('blocked_until', 0) or 0)
                if blocked_until <= current_ts:
                    blocked_until = 0

                if not recent_failures and blocked_until == 0:
                    stale_ips.append(ip_address)
                    continue

                entry['failures'] = recent_failures
                entry['blocked_until'] = blocked_until

            for ip_address in stale_ips:
                self.auth_ip_failures.pop(ip_address, None)

    def _get_auth_ip_block_seconds(self, ip_address):
        with self.auth_lock:
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return 0

            current_ts = int(time.time())
            self._prune_auth_ip_failures(current_ts)
            entry = self.auth_ip_failures.get(normalized_ip)
            if not entry:
                return 0

            blocked_until = int(entry.get('blocked_until', 0) or 0)
            if blocked_until <= current_ts:
                return 0

            return max(0, blocked_until - current_ts)

    def _record_auth_ip_failure(self, ip_address):
        with self.auth_lock:
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return 0

            current_ts = int(time.time())
            self._prune_auth_ip_failures(current_ts)
            entry = self.auth_ip_failures.setdefault(
                normalized_ip,
                {'failures': [], 'blocked_until': 0}
            )
            entry['failures'].append(current_ts)
            entry['failures'] = [
                ts for ts in entry.get('failures', [])
                if (current_ts - int(ts)) <= self.auth_ip_window_seconds
            ]

            if len(entry['failures']) >= self.auth_ip_max_failures:
                entry['blocked_until'] = current_ts + self.auth_ip_block_seconds

            return self._get_auth_ip_block_seconds(normalized_ip)

    def _clear_auth_ip_failures(self, ip_address):
        with self.auth_lock:
            normalized_ip = str(ip_address or '').strip()
            if not normalized_ip:
                return
            self.auth_ip_failures.pop(normalized_ip, None)

    @staticmethod
    def _verify_rover_password(stored_password, provided_password):
        stored_value = str(stored_password or '')
        provided_value = str(provided_password or '')

        if not stored_value:
            logger.warning(
                "Rover has an empty stored password – rejecting. "
                "Reset this rover's password through the UI."
            )
            return False

        if not stored_value.startswith('$2'):
            # Fix #4: a non-bcrypt value means the row was inserted directly
            # into SQLite (bypassing the ORM hashing) or a migration failed.
            # Previously this returned False silently, leaving the admin with
            # no clue why a valid password was being rejected. We now log it
            # loudly AND accept a one-time plaintext match so the operator can
            # log in and re-save (which re-hashes). This is gated so it only
            # helps recovery, never weakens hashed passwords.
            logger.warning(
                "Rover password is not bcrypt-hashed (legacy/plaintext row detected). "
                "Accepting a one-time plaintext comparison for recovery – "
                "re-save this rover in the UI to hash it. "
                "If you did not create this rover manually, treat this as a security event."
            )
            try:
                # Constant-time compare to avoid timing oracle on plaintext.
                import hmac
                return hmac.compare_digest(stored_value, provided_value)
            except Exception:
                return stored_value == provided_value

        try:
            return bcrypt.checkpw(
                provided_value.encode('utf-8'),
                stored_value.encode('utf-8'),
            )
        except Exception as password_error:
            logger.error(f"Error verifying rover password hash: {password_error}")
            return False
    
    def init_app(self, app):
        """Initialize server with Flask app"""
        self.app = app

    def _get_system_setting_value(self, key, default_value=''):
        if not self.app:
            return default_value

        try:
            with self.app.app_context():
                setting = SystemSetting.query.filter_by(key=str(key)).first()
                if setting and setting.value is not None:
                    return setting.value
        except Exception as setting_error:
            logger.warning(f"Unable to read system setting {key}: {setting_error}")

        return default_value

    def _get_bool_setting(self, key, default_value=True):
        default_text = 'true' if bool(default_value) else 'false'
        return str(
            self._get_system_setting_value(key, default_text)
        ).strip().lower() in ('1', 'true', 'yes', 'on')

    def _get_max_connections(self):
        try:
            configured_value = int(
                self._get_system_setting_value('max_connections', self.max_connections)
                or self.max_connections
            )
        except (TypeError, ValueError):
            configured_value = self.max_connections

        return max(1, min(int(configured_value), 1000))
    
    def start(self):
        """Start the NTRIP server"""
        if not self.app:
            raise RuntimeError("NTRIPServer must be initialized with Flask app")

        if self.running:
            logger.info("NTRIP server is already running")
            return

        with self.connection_lock:
            if self.connections:
                raise RuntimeError('Previous NTRIP handlers are still shutting down')

        if not self._get_bool_setting('ntrip_enabled', True):
            logger.info("NTRIP server is disabled by system settings")
            return
        
        # Fix #3: reset stale active_conn counters left over from a previous
        # unclean shutdown.  Do this before accepting new connections.
        try:
            with self.app.app_context():
                stale = Rover.query.filter(Rover.active_conn > 0).all()
                if stale:
                    logger.info(
                        f"NTRIP startup: resetting stale active_conn on "
                        f"{len(stale)} rover(s)"
                    )
                    for r in stale:
                        r.active_conn = 0
                    db.session.commit()
        except Exception as _reset_err:
            logger.error(f"NTRIP startup: failed to reset active_conn: {_reset_err}")
            raise

        self.running = True
        self._stop_event = threading.Event()
        
        try:
            with self.app.app_context():
                self.max_connections = self._get_max_connections()

            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.settimeout(1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(self.max_connections)
            
            logger.info(
                f"NTRIP server started on {self.host}:{self.port} "
                f"(max_connections={self.max_connections})"
            )
            
            # Start connection monitor thread
            monitor_thread = threading.Thread(
                target=self._monitor_connections,
                args=(self._stop_event,),
                daemon=True,
                name="NTRIP-Monitor"
            )
            monitor_thread.start()
            
            # Main accept loop
            accept_thread = threading.Thread(
                target=self._accept_connections,
                args=(self.server_socket, self._stop_event),
                daemon=True,
                name="NTRIP-Accept"
            )
            accept_thread.start()
            
        except Exception as e:
            logger.error(f"Failed to start NTRIP server: {e}")
            self.running = False
            self._stop_event.set()
            if self.server_socket:
                self.server_socket.close()
            raise
    
    def _read_request_headers(self, client_socket):
        """Read one bounded header block, preserving any first NMEA bytes."""
        deadline = time.monotonic() + self.header_timeout
        previous_timeout = client_socket.gettimeout()
        data = bytearray()
        try:
            while True:
                end = data.find(b'\r\n\r\n')
                if end >= 0:
                    return bytes(data[:end]), bytes(data[end + 4:])
                if len(data) >= self.header_max_bytes:
                    raise ValueError('NTRIP headers are too large')
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise socket.timeout('NTRIP header deadline exceeded')
                client_socket.settimeout(remaining)
                chunk = client_socket.recv(min(4096, self.header_max_bytes - len(data)))
                if not chunk:
                    raise EOFError('Connection closed before NTRIP headers completed')
                data.extend(chunk)
        finally:
            client_socket.settimeout(previous_timeout)

    def _reserve_rover_slot(self, rover_id, stored_password):
        # Maintenance cannot pass its idle check until this commit is visible.
        with admission_guard():
            return self._reserve_rover_slot_locked(rover_id, stored_password)

    def _reserve_rover_slot_locked(self, rover_id, stored_password):
        """Check the current limit and increment together under SQLite's writer lock."""
        result = db.session.execute(text('''
            UPDATE rover
            SET active_conn = COALESCE(active_conn, 0) + 1,
                total_connections = COALESCE(total_connections, 0) + 1,
                last_connection = :now
            WHERE id = :id AND is_active = 1 AND password = :password
              AND (COALESCE(expires, 0) = 0 OR expires >= :now)
              AND COALESCE(active_conn, 0) < max_conn
        '''), {'id': rover_id, 'password': stored_password, 'now': int(time.time())})
        if result.rowcount != 1:
            db.session.rollback()
            return False
        db.session.commit()
        return True

    def _release_rover_slot(self, rover_id):
        # Clear any failed transaction from authentication or audit logging first.
        db.session.rollback()
        db.session.execute(text('''
            UPDATE rover SET active_conn = MAX(0, COALESCE(active_conn, 0) - 1)
            WHERE id = :id
        '''), {'id': rover_id})
        db.session.commit()

    def _forget_connection(self, connection_id):
        with self.connection_lock:
            self.connections.pop(connection_id, None)
            self.stats['current_connections'] = len(self.connections)
            self.stats['rovers_connected'] = sum(
                bool(c.get('authenticated')) for c in self.connections.values()
            )

    def _start_client(self, client_socket, client_address, max_connections, stop_event=None):
        """Reserve the global slot before a handler can run or finish."""
        connection_id = str(uuid.uuid4())
        thread = threading.Thread(
            target=self._handle_client,
            args=(client_socket, client_address, connection_id),
            daemon=True,
            name=f'NTRIP-Client-{client_address[0]}:{client_address[1]}',
        )
        with self.connection_lock:
            if (not self.running or len(self.connections) >= max_connections
                    or (stop_event is not None and (
                        stop_event.is_set() or stop_event is not self._stop_event))):
                return False
            self.connections[connection_id] = {
                'thread': thread, 'socket': client_socket, 'address': client_address,
                'start_time': time.time(), 'rover': None, 'mountpoint': None,
                'authenticated': False, 'last_activity': time.time(),
            }
            self.stats['total_connections'] += 1
            self.stats['current_connections'] = len(self.connections)
        try:
            thread.start()
        except Exception:
            self._forget_connection(connection_id)
            client_socket.close()
            raise
        return True

    def _accept_connections(self, listener, stop_event):
        """Accept incoming connections"""
        while not stop_event.is_set():
            client_socket = None
            try:
                client_socket, client_address = listener.accept()
                client_socket.settimeout(30)

                max_connections = self._get_max_connections()
                self.max_connections = max_connections
                
                # Handle client in separate thread
                # Enable TCP keep-alive so the kernel probes dead clients after
                # ~60 s idle instead of hanging indefinitely (fixes #5).
                try:
                    client_socket.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
                    # Linux-specific fine-tuning (silently ignored on other OSes)
                    if hasattr(socket, 'TCP_KEEPIDLE'):
                        client_socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPIDLE, 60)
                    if hasattr(socket, 'TCP_KEEPINTVL'):
                        client_socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPINTVL, 15)
                    if hasattr(socket, 'TCP_KEEPCNT'):
                        client_socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPCNT, 4)
                except Exception as _ka_err:
                    logger.debug(f"SO_KEEPALIVE not available: {_ka_err}")

                if not self._start_client(client_socket, client_address, max_connections, stop_event):
                    try:
                        client_socket.settimeout(0.1)
                        client_socket.sendall(b"HTTP/1.1 503 Service Unavailable\r\n\r\n")
                    except OSError:
                        pass
                    client_socket.close()
                    continue
                
                logger.info(f"New connection from {client_address[0]}:{client_address[1]}")
                
            except socket.timeout:
                if client_socket is not None:
                    client_socket.close()
                continue
            except Exception as e:
                if client_socket is not None:
                    client_socket.close()
                if self.running:
                    logger.error(f"Error accepting connection: {e}")
    
    def _handle_client(self, client_socket, client_address, connection_id):
        """Handle incoming NTRIP client connection with app context"""
        with self.app.app_context():
            rover = None
            # Kept separately from the ORM object: the session is released
            # before streaming, after which only the plain id stays usable.
            rover_id = None
            rover_username = ''
            mountpoint = None
            mountpoint_id = None
            base_station_id = None
            
            try:
                client_ip = str(client_address[0] if client_address else '').strip()
                blocked_for_seconds = self._get_auth_ip_block_seconds(client_ip)
                if blocked_for_seconds > 0:
                    logger.warning(
                        f"NTRIP auth temporarily blocked for {client_ip}; "
                        f"retry in {blocked_for_seconds} seconds"
                    )
                    try:
                        client_socket.sendall(b"HTTP/1.1 429 Too Many Requests\r\n\r\n")
                    except Exception:
                        pass
                    client_socket.close()
                    with self.connection_lock:
                        self.stats['failed_auth'] += 1
                    return

                try:
                    request_data, initial_nmea = self._read_request_headers(client_socket)
                except socket.timeout:
                    client_socket.sendall(b'HTTP/1.1 408 Request Timeout\r\n\r\n')
                    return
                except ValueError:
                    client_socket.sendall(b'HTTP/1.1 431 Request Header Fields Too Large\r\n\r\n')
                    return
                except EOFError:
                    return
                try:
                    request_text = request_data.decode('ascii')
                except UnicodeDecodeError:
                    client_socket.sendall(b'HTTP/1.1 400 Bad Request\r\n\r\n')
                    return
                
                # Parse request line
                lines = request_text.strip().split('\r\n')
                if not lines:
                    logger.warning(f"Empty request from {client_address}")
                    client_socket.close()
                    return
                
                request_line = lines[0]
                if not request_line.startswith('GET '):
                    logger.warning(f"Invalid request from {client_address}: {request_line[:100]}")
                    client_socket.close()
                    return
                
                # Extract mountpoint
                parts = request_line.split(' ')
                if len(parts) < 2:
                    logger.warning(f"Malformed request line from {client_address}: {request_line}")
                    client_socket.close()
                    return
                
                mountpoint = parts[1].lstrip('/')

                # ── NTRIP Sourcetable (Fix #2) ─────────────────────────────
                # NTRIP/1.0 and NTRIP/2.0 clients ALWAYS start by requesting
                # GET / HTTP/1.0 to discover available mountpoints (sourcetable).
                # The standard (RTCM 10410.1) requires a SOURCETABLE 200 OK
                # response here WITHOUT authentication.  All standard receivers
                # (u-blox, Trimble, Leica, Emlid) check the sourcetable first.
                if mountpoint == '':
                    try:
                        with self.app.app_context():
                            mountpoints = MountPoint.query.filter_by(is_active=True).all()
                            # NB: the helper is _get_system_setting_value();
                            # calling a non-existent _get_setting() here raised
                            # AttributeError on every request, so the except
                            # branch below served an empty sourcetable and no
                            # client could ever see a mountpoint.
                            base_host = self._get_system_setting_value('caster_host') or self.host
                            caster_id = self._get_system_setting_value('caster_identifier') or 'GNSS-Caster'
                            caster_op = self._get_system_setting_value('caster_operator') or 'Unknown'
                            caster_country = self._get_system_setting_value('caster_country') or 'RUS'
                            caster_lat = self._get_system_setting_value('caster_lat') or '0.00'
                            caster_lon = self._get_system_setting_value('caster_lon') or '0.00'

                            lines_out = [
                                "SOURCETABLE 200 OK",
                                f"Server: GNSS-Caster/{CASTER_VERSION}",
                                "Content-Type: text/plain",
                                "Connection: close",
                                "",
                                # Caster record
                                (
                                    f"CAS;{base_host};{self.port};"
                                    f"{caster_id};{caster_op};0;"
                                    f"{caster_country};{caster_lat};{caster_lon};0;0;"
                                    f"http://{base_host}/sourcetable.txt"
                                ),
                            ]
                            for mp in mountpoints:
                                # Determine base station position if available
                                lat, lon, alt = '0.00', '0.00', '0'
                                base = None
                                try:
                                    base = mp.base_station
                                    if base and base.manual_lat:
                                        lat = f"{float(base.manual_lat):.4f}"
                                        lon = f"{float(base.manual_lon):.4f}"
                                        alt = f"{float(base.manual_alt or 0):.1f}"
                                except Exception:
                                    pass
                                nav_sys = 'GPS+GLO+GAL+BDS'
                                carrier = '2'        # L1+L2
                                nmea = '0'
                                solution = '1'       # Network
                                generator = mp.description or 'GNSS-Caster'
                                fee = 'N'
                                bitrate = '9600'
                                misc = ''
                                # STR;mountpoint;identifier;format;format-details;
                                #     carrier;nav-system;network;country;lat;lon;
                                #     nmea;solution;generator;compr-encr;auth;
                                #     fee;bitrate;misc
                                lines_out.append(
                                    f"STR;{mp.name};{mp.name};RTCM 3.2;;{carrier};"
                                    f"{nav_sys};;{caster_country};"
                                    f"{lat};{lon};{nmea};{solution};"
                                    f"{generator};none;B;{fee};{bitrate};{misc}"
                                )
                            lines_out.append("ENDSOURCETABLE")
                            body = "\r\n".join(lines_out) + "\r\n"
                        client_socket.sendall(body.encode('ascii'))
                    except Exception as _st_err:
                        logger.error(f"Error sending sourcetable: {_st_err}")
                        try:
                            client_socket.sendall(
                                b"SOURCETABLE 200 OK\r\n\r\nENDSOURCETABLE\r\n"
                            )
                        except Exception:
                            pass
                    finally:
                        try:
                            client_socket.close()
                        except Exception:
                            pass
                    # Remove from connections tracking (no rover, never authenticated)
                    with self.connection_lock:
                        to_remove = [
                            cid for cid, info in self.connections.items()
                            if info.get('socket') == client_socket
                        ]
                        for cid in to_remove:
                            del self.connections[cid]
                        self.stats['current_connections'] = len(self.connections)
                    return

                # ── Authenticated mountpoint access ─────────────────────────
                # Extract authorization
                auth_header = None
                for line in lines:
                    if line.lower().startswith('authorization:'):
                        auth_header = line
                        break
                
                if not auth_header:
                    logger.warning(f"No authorization header from {client_address}")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    with self.connection_lock:
                        self.stats['failed_auth'] += 1
                    return
                
                # Parse credentials
                try:
                    auth_scheme, auth_token = auth_header.split(':', 1)[1].strip().split()
                    if auth_scheme.lower() != 'basic':
                        raise ValueError('Unsupported authorization scheme')
                    credentials = base64.b64decode(auth_token, validate=True).decode('ascii')
                    username, password = credentials.split(':', 1)
                except Exception as e:
                    logger.warning(f"Invalid auth header from {client_address}: {e}")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    with self.connection_lock:
                        self.stats['failed_auth'] += 1
                    return
                
                # Validate rover
                rover = Rover.query.filter_by(username=username).first()
                if not rover:
                    logger.warning(f"Unknown rover username: {username} from {client_address}")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    with self.connection_lock:
                        self.stats['failed_auth'] += 1
                    return
                
                # Check if rover is active
                if not rover.is_active:
                    logger.warning(f"Rover {username} is inactive")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    return
                
                # Check password
                if not self._verify_rover_password(rover.password, password):
                    logger.warning(f"Invalid password for rover: {username} from {client_address}")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    with self.connection_lock:
                        self.stats['failed_auth'] += 1
                    return

                # Fix #4: if the stored password was legacy plaintext, upgrade it
                # to bcrypt now that we've confirmed the credential is correct.
                if not str(rover.password or '').startswith('$2'):
                    try:
                        rover.password = bcrypt.hashpw(
                            password.encode('utf-8'), bcrypt.gensalt()
                        ).decode('utf-8')
                        db.session.commit()
                        logger.info(
                            f"Rover {username}: legacy password upgraded to bcrypt on login"
                        )
                    except Exception as _rehash_err:
                        db.session.rollback()
                        logger.error(
                            f"Rover {username}: failed to upgrade legacy password: {_rehash_err}"
                        )
                
                # Check expiration
                if rover.expires > 0 and rover.expires < time.time():
                    logger.warning(f"Rover {username} expired")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    return
                
                # Check mountpoint access
                allowed_mountpoints = (rover.mountpoints or "").split(',')
                if mountpoint not in allowed_mountpoints and allowed_mountpoints != ['']:
                    logger.warning(f"Rover {username} not authorized for mountpoint {mountpoint}")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    return
                
                # Get mountpoint
                mountpoint_obj = MountPoint.query.filter_by(name=mountpoint).first()
                if not mountpoint_obj or not mountpoint_obj.is_active:
                    logger.warning(f"Mountpoint {mountpoint} not found or inactive")
                    self._record_auth_ip_failure(client_ip)
                    client_socket.close()
                    return
                
                # Snapshot scalars before commit expires the ORM instances.
                candidate_rover_id = rover.id
                rover_username = str(rover.username or '')
                stored_password = rover.password
                mountpoint_id = mountpoint_obj.id
                base_station_id = mountpoint_obj.base_id
                mountpoint_name = str(mountpoint_obj.name or '')
                try:
                    reserved = self._reserve_rover_slot(candidate_rover_id, stored_password)
                except OSError:
                    logger.info('Rover admission unavailable during maintenance')
                    client_socket.sendall(b'HTTP/1.1 503 Service Unavailable\r\nRetry-After: 30\r\n\r\n')
                    return
                if not reserved:
                    logger.warning('Rover slot unavailable or credentials changed for %s', rover_username)
                    return
                # Set only after a successful commit: rejected clients must not
                # decrement a slot owned by another connection in finally.
                rover_id = candidate_rover_id
                self._clear_auth_ip_failures(client_ip)

                notify.send(
                    self.app,
                    f'\U0001f4e1 Rover "{rover_username}" started receiving corrections.',
                    event='notify_rover_connect',
                    event_key=f'rover-up-{rover_id}',
                    cooldown=30.0,
                )
                
                # Update connection info
                with self.connection_lock:
                    conn_info = self.connections.get(connection_id)
                    if not self.running or conn_info is None:
                        return
                    conn_info.update({
                        'rover': rover_username, 'rover_id': rover_id,
                        'mountpoint': mountpoint, 'mountpoint_id': mountpoint_id,
                        'base_station': base_station_id, 'authenticated': True,
                        'last_activity': time.time(),
                    })
                    
                    self.stats['rovers_connected'] = len([c for c in self.connections.values() if c.get('authenticated')])
                
                # Send successful response
                response = "ICY 200 OK\r\n\r\n"
                client_socket.sendall(response.encode('ascii'))
                # Fixed timeout shared by the reader and its dedicated sender.
                client_socket.settimeout(2)
                stream_manager.register_client(base_station_id, mountpoint_id, client_socket)
                
                logger.info(f"Rover {username} connected to mountpoint {mountpoint} from {client_address[0]}")
                
                # Log connection
                log_entry = LogEntry(
                    level="INFO",
                    module="ntrip",
                    message=f"Rover {username} connected to {mountpoint} from {client_address[0]}",
                    timestamp=int(time.time()),
                    ip_address=client_address[0]
                )
                db.session.add(log_entry)
                db.session.commit()

                # Release the database session before entering the streaming
                # loop below. A rover stays connected for hours, and holding
                # this session open for that long pinned a SQLite connection
                # and its transaction: editing a base station from the web UI
                # then collided with it, which dropped the rover and stopped
                # new rovers from authenticating until the host was rebooted.
                # Later database work in this thread opens a fresh session on
                # demand, so nothing else needs to change.
                db.session.remove()

                # Keep connection alive and read rover NMEA (GGA for VRS).
                # We use a short socket read timeout so we can both:
                #   (a) detect dead connections promptly, and
                #   (b) capture GGA sentences the rover pushes back (NTRIP/2.0),
                #       forwarding them to the base receiver for network RTK.
                gga_buffer = b''
                last_heartbeat = time.time()

                while self.running:
                    try:
                        try:
                            if initial_nmea:
                                chunk, initial_nmea = initial_nmea, b''
                            else:
                                chunk = client_socket.recv(512)
                        except socket.timeout:
                            chunk = None
                        except BlockingIOError:
                            chunk = None
                        except OSError as _sock_err:
                            logger.debug(f"Socket dead for {rover_username}: {_sock_err}")
                            break

                        if chunk == b'':
                            # Clean FIN from peer.
                            logger.debug(f"Peer closed connection for {rover_username}")
                            break

                        if chunk:
                            # Accumulate and extract complete NMEA lines.
                            gga_buffer += chunk
                            if len(gga_buffer) > 4096:
                                # Guard against a misbehaving client flooding us.
                                gga_buffer = gga_buffer[-1024:]

                            while b'\n' in gga_buffer:
                                line, gga_buffer = gga_buffer.split(b'\n', 1)
                                text_line = line.decode('ascii', errors='ignore').strip()
                                if 'GGA' in text_line[:7] and base_station_id is not None:
                                    try:
                                        from app.bluetooth.core import bluetooth_manager as _bt_mgr
                                        _bt_mgr.forward_gga_to_station(
                                            base_station_id, text_line
                                        )
                                    except Exception as _fwd_err:
                                        logger.debug(
                                            f"GGA forward error for {rover_username}: {_fwd_err}"
                                        )

                            with self.connection_lock:
                                if connection_id in self.connections:
                                    self.connections[connection_id]['last_activity'] = time.time()

                        # Periodic keep-alive bookkeeping (every ~30 s).
                        now = time.time()
                        if (now - last_heartbeat) >= 30:
                            last_heartbeat = now
                            with self.connection_lock:
                                if connection_id in self.connections:
                                    self.connections[connection_id]['last_activity'] = now

                    except Exception as e:
                        logger.debug(f"Connection error for {rover_username}: {e}")
                        break
            
            except Exception as e:
                logger.error(f"Error handling client {client_address}: {e}")
            
            finally:
                if base_station_id is not None and mountpoint_id is not None:
                    try:
                        stream_manager.unregister_client(base_station_id, mountpoint_id, client_socket)
                    except Exception as stream_error:
                        logger.error(f"Error unregistering rover stream: {stream_error}")

                if rover_id is not None:
                    try:
                        self._release_rover_slot(rover_id)
                    except Exception as e:
                        logger.error(f"Error updating rover connection count: {e}")
                    finally:
                        db.session.remove()

                self._forget_connection(connection_id)
                
                try:
                    client_socket.close()
                except Exception:
                    pass
                
                if rover_id is not None:
                    logger.info(f"Rover {rover_username} disconnected from {mountpoint}")
                    notify.send(
                        self.app,
                        f'\U0001f50c Rover "{rover_username}" stopped.',
                        event='notify_rover_disconnect',
                        event_key=f'rover-down-{rover_id}',
                        cooldown=30.0,
                    )
                    
                    # Log disconnection with app context
                    with self.app.app_context():
                        try:
                            log_entry = LogEntry(
                                level="INFO",
                                module="ntrip",
                                message=f"Rover {rover_username} disconnected from {mountpoint}",
                                timestamp=int(time.time())
                            )
                            db.session.add(log_entry)
                            db.session.commit()
                        except Exception as e:
                            logger.error(f"Error logging disconnection: {e}")
    
    def _monitor_connections(self, stop_event):
        """Monitor and log connection statistics with app context"""
        while not stop_event.is_set():
            try:
                with self.app.app_context():
                    with self.connection_lock:
                        current_connections = self.stats['current_connections']
                        total_connections = self.stats['total_connections']
                        failed_auth = self.stats['failed_auth']
                        rovers_connected = self.stats['rovers_connected']
                    
                    # Get active rover connections from database
                    active_rovers = 0
                    try:
                        rovers = Rover.query.all()
                        active_rovers = sum(r.active_conn for r in rovers)
                    except Exception as e:
                        logger.error(f"Error getting rover stats: {e}")
                    
                    # Routine heartbeat: DEBUG so it does not fill the log (and
                    # the SD card) with a line every minute forever.
                    logger.debug(f"NTRIP: {current_connections} active, {total_connections} total, "
                               f"Failed auth: {failed_auth}, Rovers active: {active_rovers} ({rovers_connected} authenticated)")
                
                stop_event.wait(60)  # Wake immediately on stop, including before restart.
                
            except Exception as e:
                logger.error(f"Error in connection monitor: {e}")
                stop_event.wait(30)
    
    def stop(self):
        """Stop the NTRIP server"""
        logger.info("Stopping NTRIP server")
        self.running = False
        self._stop_event.set()
        
        # Keep registrations until each handler has released its database slot.
        # start() refuses to reset counters while any old handler remains.
        with self.connection_lock:
            connections = list(self.connections.values())
        for conn_info in connections:
            client_socket = conn_info['socket']
            stream_manager.unregister_client_socket(client_socket)
            try:
                client_socket.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            client_socket.close()
        
        # Close server socket
        if self.server_socket:
            try:
                self.server_socket.close()
            except Exception:
                pass

        deadline = time.monotonic() + 5
        for conn_info in connections:
            thread = conn_info['thread']
            if thread is not threading.current_thread() and thread.ident is not None:
                thread.join(timeout=max(0, deadline - time.monotonic()))
        
        logger.info("NTRIP server stopped")
    
    def get_status(self):
        """Get server status and statistics"""
        with self.connection_lock:
            connections = []
            for conn_info in self.connections.values():
                if conn_info.get('authenticated'):
                    connections.append({
                        'rover': conn_info['rover'],
                        'rover_id': conn_info.get('rover_id'),
                        'mountpoint': conn_info.get('mountpoint'),
                        'mountpoint_id': conn_info.get('mountpoint_id'),
                        'address': f"{conn_info['address'][0]}:{conn_info['address'][1]}",
                        'duration': time.time() - conn_info.get('start_time', 0),
                        'last_activity': conn_info.get('last_activity'),
                        'authenticated': conn_info.get('authenticated', False)
                    })
            
            stats = dict(self.stats)
            stats['authenticated_connections'] = len([c for c in self.connections.values() if c.get('authenticated')])
        
        return {
            'running': self.running,
            'host': self.host,
            'port': self.port,
            'max_connections': self.max_connections,
            'stats': stats,
            'connections': connections
        }

# Global instance
ntrip_server = NTRIPServer()
EOF

