        app.config['WEB_PORT'] = int(server_config.get('web_port', 8080) or 8080)
        app.config['NTRIP_PORT'] = int(server_config.get('ntrip_port', 2101) or 2101)
        app.config['LOG_LEVEL'] = _normalize_log_level(
