        @app.route('/api/bluetooth/connect', methods=['POST'])
        @login_required
        def api_bluetooth_connect():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json or {}
                mac = str(data.get('mac', '')).strip()
                timeout = int(data.get('timeout', 20))
                pin_code = str(data.get('pin', '')).strip()

                if not mac:
                    return jsonify({'error': 'Missing MAC address'}), 400
                if pin_code and len(pin_code) > 16:
                    return jsonify({'error': 'PIN code must be 16 characters or less'}), 400

                from app.bluetooth.core import bluetooth_manager

                configured = [
                    station for station in BaseStation.query.all()
                    if str(station.bt_mac or '').strip().upper() == mac.upper()
                    and str(station.connection_type or 'bluetooth').strip().lower()
                    in ('bluetooth', 'ble', 'bluetooth_le', 'bluetooth-le')
                ]
                if len(configured) > 1:
                    return jsonify({'error': 'Multiple base stations use this Bluetooth address'}), 409
                if configured:
                    # Known receivers already have a transport worker. BlueZ
                    # Pair/Connect may select LE on a dual-mode SPP receiver and
                    # cannot restore that worker's RFCOMM data socket.
                    success, message, state = bluetooth_manager.request_station_connection(configured[0].id)
                    return jsonify({
                        'success': success, 'message': message, 'mac': mac,
                        'managed_station': True, 'connection_state': state,
                    }), (200 if success else 503)

                success, message = bluetooth_manager.dbus_client.connect_device(
                    mac,
                    timeout=max(timeout, 10),
                    scan_timeout=max(timeout, 8),
                    pin_code=pin_code or None,
                )

                return jsonify({
                    'success': bool(success),
                    'message': message,
                    'mac': mac,
                })
            except Exception as e:
                logger.error(f"Error connecting Bluetooth device: {e}")
                return jsonify({'error': str(e)}), 500

