        @app.route('/api/rtcm/presets')
        @login_required
        def api_rtcm_presets():
            try:
                presets = _load_rtcm_presets()
                result = []

                for name, entry in presets.items():
                    if not isinstance(name, str):
                        continue

                    settings_map = _resolve_preset_settings(entry)
                    if not settings_map:
                        continue

                    enabled_count = sum(1 for value in settings_map.values() if _parse_bool(value))
                    total_count = len(settings_map)
                    saved_at = 0
                    if isinstance(entry, dict):
                        try:
                            saved_at = int(entry.get('saved_at', 0) or 0)
                        except Exception:
                            saved_at = 0

                    result.append({
                        'name': name,
                        'enabled_count': enabled_count,
                        'total_count': total_count,
                        'saved_at': saved_at,
                    })

                result.sort(key=lambda x: x['name'].lower())
                return jsonify({'presets': result})
            except Exception as e:
                logger.error(f"Error getting RTCM presets: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/rtcm/presets/save', methods=['POST'])
        @login_required
        def api_save_rtcm_preset():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json or {}
                preset_name = str(data.get('name', '')).strip()
                if not preset_name:
                    return jsonify({'error': 'Preset name is required'}), 400

                if len(preset_name) > 48:
                    return jsonify({'error': 'Preset name must be 48 characters or less'}), 400

                raw_settings = data.get('settings')
                if raw_settings is None:
                    normalized_settings = _get_current_rtcm_settings_map()
                else:
                    normalized_settings = _normalize_rtcm_settings_map(raw_settings)

                if not normalized_settings:
                    return jsonify({'error': 'Preset settings are empty'}), 400

                presets = _load_rtcm_presets()
                presets[preset_name] = {
                    'settings': normalized_settings,
                    'saved_at': int(time.time()),
                }

                _save_rtcm_presets(presets)
                db.session.commit()
                return jsonify({
                    'message': f'Preset "{preset_name}" saved',
                    'name': preset_name,
                    'count': len(normalized_settings),
                }), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error saving RTCM preset: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/rtcm/presets/apply', methods=['POST'])
        @login_required
        def api_apply_rtcm_preset():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json or {}
                preset_name = str(data.get('name', '')).strip()
                if not preset_name:
                    return jsonify({'error': 'Preset name is required'}), 400

                presets = _load_rtcm_presets()
                preset_entry = presets.get(preset_name)
                if preset_entry is None:
                    return jsonify({'error': 'Preset not found'}), 404

                normalized_settings = _resolve_preset_settings(preset_entry)
                if not normalized_settings:
                    return jsonify({'error': 'Preset has no valid RTCM settings'}), 400

                updated_count = 0
                now_ts = int(time.time())

                for msg_type_str, enabled in normalized_settings.items():
                    msg_type = int(msg_type_str)
                    setting = RTCMSetting.query.filter_by(msg_type=msg_type).first()

                    if setting:
                        setting.enabled = enabled
                        setting.updated_at = now_ts
                    else:
                        setting = RTCMSetting(
                            msg_type=msg_type,
                            enabled=enabled,
                            description=get_message_description(msg_type),
                            version='3.2',
                            group=get_message_group(msg_type)
                        )
                        db.session.add(setting)

                    updated_count += 1

                db.session.commit()
                return jsonify({
                    'message': f'Preset "{preset_name}" applied',
                    'count': updated_count,
                }), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error applying RTCM preset: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/rtcm/presets/delete', methods=['POST'])
        @login_required
        def api_delete_rtcm_preset():
            try:
                role_error = _require_operator_role()
                if role_error:
